#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
#  v4 (2026-10-12) - poprawki po analizie backtestu i logow LIVE:
#   1) MIN. ROZMIAR ZLECENIA: CLOB odrzuca <5 share'ow. Przy stawce 1$ i ask>0.20
#      zlecenie BUY nie moglo sie wypelnic -> bot chodzil, ale nie otwieral pozycji.
#      Teraz stawka rosnie do min. 5 share'ow (albo rynek jest pomijany).
#   2) TIME-EXIT FINANCE: bylo 2h (na backteście ~0%/pozycja, win ~48%). Teraz 12h
#      (FIN_EXIT_HOURS=12; na danych 12-24h dawalo +17..27%/pozycja).
#   3) ZAKRES CENY: Finance gra tylko ask <= FIN_MAX_ASK (0.25) - tanie rynki mialy
#      ~+27%/pozycja, drozsze rozwadnialy wynik do ~+12%.
#   4) OPLATY: paper liczy teraz realny taker fee = shares*rate*p*(1-p) DWUSTRONNIE
#      (Finance rate 0.04), zamiast 2% tylko od sprzedazy.
#   5) LIVE_MAX_EXPOSURE domyslnie 25$ (bylo 100000 = brak bezpiecznika).
#   6) Banner wypisuje tylko realnie wlaczone strategie (Finance).
#  Diagnostyka: DEBUG_CAT=1 -> linie [FIN-SUMMARY]/[FIN-SKIP] (ile sygnalow, ile
#  pominieto z powodu min. rozmiaru/budzetu).
# ============================================================================
# ============================================================================
#  finance_6h_v4.sh  --  JEDEN skrypt: pobiera, instaluje, buduje LIVE i uruchamia bota.
# ----------------------------------------------------------------------------
#  UZYCIE:
#     bash finance_6h_v4.sh          -> LIVE (prawdziwe pieniadze)   [domyslnie]
#     bash finance_6h_v4.sh dry      -> PAPER (na sucho, bez kasy)
#     bash finance_6h_v4.sh doctor   -> tylko sprawdzenie portfela i salda
#     bash finance_6h_v4.sh build    -> tylko buduje (stary bot dziala dalej)
#     bash finance_6h_v4.sh run      -> uruchamia juz zbudowany plik
#
#  Skrypt jest SAMOWYSTARCZALNY: ma w sobie caly kod (Cargo.toml + main.rs)
#  oraz NAPRAWE TLS dla Androida/Termux (shim rustls-platform-verifier).
#  KONFIGURACJA (FINANCE-2, okno 6h): 2 strategie TYLKO na Finance (tag 120),
#  SL -90%, time-exit 2h, spread <= 0.03$:
#    A40_40: drop -40% (od maksimum z 6h) / TP +40%
#    C30_30: drop -30% (od maksimum z 6h) / TP +30%
#  NIE dubluja sie (jeden rynek = jedna strategia). Max 10 pozycji na strategie,
#  limit lacznie MAX_POSITIONS=20.
#  Stawka startowa 1$ (dynamiczna: +10% co +20% bankrolla). BEZ filtra wolumenu,
#  guard na realna ksiazke (bid <= ask). START_BUDGET=20.9.
#  START Z HISTORIA: przy uruchomieniu bot sam wczytuje ostatnie 6h cen (CLOB
#  prices-history, 1 pkt/min), wiec okno 6h dziala OD RAZU - bez czekania 6 godzin.
#  Linie [BOOT] w logu pokazuja postep. Wylacz: BOOT_HISTORY=0
#  Wszystkie inne strategie (crypto S2-S9, sports live) i inne kategorie WYLACZONE.
# ============================================================================
set -e
cd "$HOME" 2>/dev/null || cd /data/data/com.termux/files/home

MODE="${1:-live}"

say(){  printf '\n\033[1;32m==> %s\033[0m\n' "$*"; }
warn(){ printf '\n\033[1;33m[!] %s\033[0m\n' "$*"; }
err(){  printf '\n\033[1;31m[X] %s\033[0m\n' "$*"; }

# ---------------------------------------------------------------------------
#  TRYB 'run'  --  uruchamia JUZ ZBUDOWANY plik binarny (bez pobierania/budowania).
#  Zastosowanie (bezpieczna aktualizacja bez zamykania pozycji):
#     1) w DRUGIEJ sesji Termux:  bash finance_6h_v4.sh build      (stary bot DZIALA dalej)
#     2) gdy build sie skonczy:   Ctrl+C starego bota
#     3) natychmiast:             bash finance_6h_v4.sh run
#  Przerwa w kontroli pozycji to kilka SEKUND (a nie 10-15 min przebudowy).
#  Stan (positions.json) jest zachowany -> bot wraca do tych samych pozycji i TP/SL.
# ---------------------------------------------------------------------------
if [ "$MODE" = "run" ]; then
  cd "$HOME/pm-rust" 2>/dev/null || cd /data/data/com.termux/files/home/pm-rust
  if [ -f "$HOME/.poly_env" ]; then . "$HOME/.poly_env"; fi
  export POLYMARKET_PRIVATE_KEY
  export LIVE=1
  export CONFIRM_LIVE=I_UNDERSTAND_THE_RISK
  export LIVE_MAX_EXPOSURE="${LIVE_MAX_EXPOSURE:-25}"
  export MAX_SPREAD_CENTS="${MAX_SPREAD_CENTS:-0.03}"
  export FIN_EXIT_HOURS="${FIN_EXIT_HOURS:-12}"
  export FIN_MAX_ASK="${FIN_MAX_ASK:-0.25}"
  export START_BUDGET="${START_BUDGET:-20.9}"
export MAX_POSITIONS="${MAX_POSITIONS:-20}"
export CAT_MAX_PAGES="${CAT_MAX_PAGES:-25}"
  export SPORTS_MIN_VOLUME="${SPORTS_MIN_VOLUME:-250}"
  export SPORTS_MAX_VOLUME="${SPORTS_MAX_VOLUME:-20000}"
  export SPORTS_MAX_MARKETS="${SPORTS_MAX_MARKETS:-2000}"
  export SPORTS_MAX_PAGES="${SPORTS_MAX_PAGES:-5}"
  export SPORTS_DROP="${SPORTS_DROP:-0.40}"
  export SPORTS_REFRESH_SEC="${SPORTS_REFRESH_SEC:-30}"
  printf '\n\033[1;36m[RUN] LIVE_MAX_EXPOSURE=%s  spread<=%s  ask<=%s  hold=%sh  START_BUDGET=%s  (limit poz: 20)\033[0m\n' "$LIVE_MAX_EXPOSURE" "$MAX_SPREAD_CENTS" "$FIN_MAX_ASK" "$FIN_EXIT_HOURS" "$START_BUDGET"
  exec ./target/release/pm-rust
fi

say "1/6 Instaluje zaleznosci (rust, git, openssl, coreutils)..."
pkg update -y >/dev/null 2>&1 || true
pkg install -y rust git openssl coreutils >/dev/null 2>&1 \
  || pkg install -y rust git openssl >/dev/null 2>&1 || true

export PATH="$HOME/.cargo/bin:$PATH"
if ! command -v cargo >/dev/null 2>&1; then
  err "Nie widze 'cargo'. Zainstaluj recznie: pkg install rust"
  exit 1
fi
if command -v rustup >/dev/null 2>&1; then
  rustup default stable >/dev/null 2>&1 || true
fi

say "2/6 Tworze ~/pm-rust i pliki projektu (z naprawa TLS)..."
mkdir -p "$HOME/pm-rust/src" "$HOME/pm-rust/vendor/rustls-platform-verifier/src"
cd "$HOME/pm-rust"

cat > Cargo.toml <<'CARGOEOF'
[package]
name = "pm-rust"
version = "0.1.0"
edition = "2021"

[[bin]]
name = "pm-rust"
path = "src/main.rs"

[dependencies]
anyhow = "1"
serde = { version = "1", features = ["derive"] }
serde_json = "1"
tokio = { version = "1", features = ["macros", "rt-multi-thread", "time", "sync"] }
reqwest = { version = "0.12", default-features = false, features = ["json", "rustls-tls", "http2"] }
rustls = { version = "0.23", default-features = false, features = ["ring", "std", "tls12"] }
webpki-roots = "0.26"
# SDK potrzebny TYLKO do skladania prawdziwych zlecen (feature "live").
polymarket_client_sdk_v2 = { version = "0.8.0", features = ["clob"], optional = true }

[features]
default = []
live = ["dep:polymarket_client_sdk_v2"]

# NAPRAWA TERMUX/ANDROID:
# SDK (reqwest 0.13 z "rustls-tls-native-roots") ciagnie rustls-platform-verifier,
# ktory na Androidzie wymaga JNI i PANIKUJE przy pierwszym zleceniu LIVE:
#   "Expect rustls-platform-verifier to be initialized"
# Podmieniamy go na lokalny shim uzywajacy wbudowanych certyfikatow webpki-roots.
[patch.crates-io]
rustls-platform-verifier = { path = "vendor/rustls-platform-verifier" }
CARGOEOF

base64 -d > src/main.rs <<'B64EOF'
